<script setup>
import { reactive, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue';
const props=defineProps({record:Object,editing:Boolean,saving:Boolean,error:String,safeAreaStyle:Object});const emit=defineEmits(['cancel','save']);const draft=reactive({name:'',url:'',type:'news',enabled:true});function reset(record){Object.assign(draft,{name:String(record?.name||''),url:String(record?.url||''),type:['news','social','website','other'].includes(record?.type)?record.type:'news',enabled:record?.enabled!==false});}watch(()=>props.record,reset,{immediate:true,deep:true});const types=[{value:'news',label:'Báo chí'},{value:'social',label:'Mạng xã hội'},{value:'website',label:'Website'},{value:'other',label:'Khác'}];const states=[{value:true,label:'Bật'},{value:false,label:'Tắt'}];function submit(){emit('save',{...draft});}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="editing?'Sửa nguồn tin':'Thêm nguồn tin'" @back="emit('cancel')"/><form class="min-h-0 flex-1 overflow-y-auto" @submit.prevent="submit"><div class="mds-mobile-gutter-x space-y-4 py-4"><p v-if="error" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{error}}</p><label><span class="mb-1 block text-[13px] font-medium">Tên nguồn</span><MInput v-model="draft.name" placeholder="VnExpress"/></label><label><span class="mb-1 block text-[13px] font-medium">URL</span><MInput v-model="draft.url" type="url" placeholder="https://..."/></label><label><span class="mb-1 block text-[13px] font-medium">Loại</span><MSelect v-model="draft.type" :options="types"/></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.enabled" :options="states"/></label></div><footer class="flex gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="neutral" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" :loading="saving" @click="submit">{{editing?'Lưu':'Thêm'}}</MButton></footer></form></section></template>
